package com.myles.kotobafloat;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;import java.lang.reflect.*;import java.util.*;import java.io.*;
/** 七类设置逐页验证实际文字尺寸与三语主题选择器。 / Check measured text on every settings page and the localized palette. */
@android.annotation.TargetApi(29)
public final class Feature195Layouts extends Instrumentation {
    private String language,theme;private int rotation;private MainActivity activity;private int checks;
    @Override public void onCreate(Bundle args){super.onCreate(args);language=args.getString("language","ZH");theme=args.getString("theme","DARK");rotation=Integer.parseInt(args.getString("rotation","0"));start();}
    private void ui(Runnable action){java.util.concurrent.atomic.AtomicReference<Throwable> error=new java.util.concurrent.atomic.AtomicReference<>();runOnMainSync(()->{try{action.run();}catch(Throwable e){error.set(e);}});if(error.get()!=null)throw new AssertionError("Layout assertion failed",error.get());}
    private Object field(String name){try{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}catch(Exception e){throw new RuntimeException(e);}}
    private void render(int category){try{for(String name:new String[]{"tab","settingsCategory"}){Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);f.setInt(activity,name.equals("tab")?3:category);}Method m=MainActivity.class.getDeclaredMethod("render");m.setAccessible(true);m.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}}
    private void verify(View v){if(v.getVisibility()!=View.VISIBLE)return;if(v instanceof TextView){TextView t=(TextView)v;if(t.getText().length()>0&&t.getLayout()!=null){if(t.getLayout().getHeight()+t.getCompoundPaddingTop()+t.getCompoundPaddingBottom()>t.getHeight()+2)throw new AssertionError("Text clipped: "+t.getText()+" needs "+t.getLayout().getHeight()+" in "+t.getHeight());checks++;}}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)verify(((ViewGroup)v).getChildAt(i));}
    private void shot(String suffix)throws Exception{Bitmap bitmap=getUiAutomation().takeScreenshot();if(bitmap==null)throw new AssertionError("No screenshot");String file="layout195-"+language+"-"+suffix+".png";try(FileOutputStream stream=getTargetContext().openFileOutput(file,0)){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}bitmap.recycle();}
    @Override public void onStart(){Bundle result=new Bundle();try{
        if(!Build.HARDWARE.equals("ranchu")&&!Build.HARDWARE.equals("goldfish"))throw new AssertionError("Emulator only");Prefs prefs=new Prefs(getTargetContext());prefs.data.edit().putString("theme",theme).putString("accent","BLACK").putString("uiLanguage",language).putBoolean("languagePromptSeen",true).putBoolean("languagePromptPending",false).putBoolean("autoSpeak",false).commit();activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));long until=SystemClock.elapsedRealtime()+20000;while(SystemClock.elapsedRealtime()<until){boolean[] ready={false};ui(()->ready[0]=field("cachedHome")!=null);if(ready[0])break;SystemClock.sleep(20);}
        ui(()->{if(Ui.night(activity)!=theme.equals("DARK"))throw new AssertionError("Theme mismatch");if(activity.getResources().getConfiguration().orientation!=(rotation==0?1:2))throw new AssertionError("Orientation mismatch: "+activity.getResources().getConfiguration());checks+=2;});
        for(int i=0;i<7;i++){final int category=i;ui(()->render(category));waitForIdleSync();SystemClock.sleep(80);ui(()->verify(activity.getWindow().getDecorView()));if(i==0||i==2||i==4)shot("settings"+i);}
        ui(()->ThemePicker.show(activity,prefs,()->{},()->{}));waitForIdleSync();SystemClock.sleep(80);ui(()->{List<View> roots=android.view.inspector.WindowInspector.getGlobalWindowViews();View root=roots.get(roots.size()-1);verify(root);View cancel=root.findViewById(android.R.id.button2);if(cancel==null||cancel.getHeight()<Ui.dp(activity,40))throw new AssertionError("Cancel action inaccessible");checks++;});shot("palette");ui(()->activity.finish());result.putString("stream","PASS: "+checks+" measured 1.9.5 layout checks in "+language+"\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable error){result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
}
